Here is the commit message:
ipv6: fix possible UAF in icmpv6_rcv()

Caching saddr and daddr before pskb_pull() is problematic
since skb->head can change.

Remove these temporary variables:

- We only access &ipv6_hdr(skb)->saddr and &ipv6_hdr(skb)->daddr
  when net_dbg_ratelimited() is called in the slow path.

- Avoid potential future misuse after pskb_pull() call.

Fixes: 4b3418fba0fe ("ipv6: icmp: include addresses in debug messages")
Signed-off-by: Eric Dumazet <edumazet@google.com>
Reviewed-by: Fernando Fernandez Mancera <fmancera@suse.de>
Reviewed-by: Joe Damato <joe@dama.to>
Reviewed-by: Ido Schimmel <idosch@nvidia.com>
Link: https://patch.msgid.link/20260416103505.2380753-1-edumazet@google.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function `icmpv6_rcv()` cached pointers to the source and destination IPv6 addresses (`saddr`, `daddr`) before a `pskb_pull()` call that can change `skb->head`. After `pskb_pull()`, the cached pointers become stale, leading to a use-after-free when these pointers are later dereferenced in debug logging (`net_dbg_ratelimited`). The fix removes the cached pointers and accesses the IPv6 header fields directly at the usage point.

Here is the patch:

 static int icmpv6_rcv(struct sk_buff *skb)
 {
 	enum skb_drop_reason reason = SKB_DROP_REASON_NOT_SPECIFIED;
 	struct net *net = dev_net_rcu(skb->dev);
 	struct net_device *dev = icmp6_dev(skb);
 	struct inet6_dev *idev = __in6_dev_get(dev);
-	const struct in6_addr *saddr, *daddr;
 	struct icmp6hdr *hdr;
 	u8 type;

 	if (!xfrm6_policy_check(NULL, XFRM_POLICY_IN, skb)) {
 		struct sec_path *sp = skb_sec_path(skb);
 		int nh;

 		if (!(sp && sp->xvec[sp->len - 1]->props.flags &
 				 XFRM_STATE_ICMP)) {
 			reason = SKB_DROP_REASON_XFRM_POLICY;
 			goto drop_no_count;
 		}

 		if (!pskb_may_pull(skb, sizeof(*hdr) + sizeof(struct ipv6hdr)))
 			goto drop_no_count;

 		nh = skb_network_offset(skb);
 		skb_set_network_header(skb, sizeof(*hdr));

 		if (!xfrm6_policy_check_reverse(NULL, XFRM_POLICY_IN,
 						skb)) {
 			reason = SKB_DROP_REASON_XFRM_POLICY;
 			goto drop_no_count;
 		}

 		skb_set_network_header(skb, nh);
 	}

 	__ICMP6_INC_STATS(dev_net_rcu(dev), idev, ICMP6_MIB_INMSGS);

-	saddr = &ipv6_hdr(skb)->saddr;
-	daddr = &ipv6_hdr(skb)->daddr;
-
 	if (skb_checksum_validate(skb, IPPROTO_ICMPV6, ip6_compute_pseudo)) {
 		net_dbg_ratelimited("ICMPv6 checksum failed [%pI6c > %pI6c]\n",
-				    saddr, daddr);
+				    &ipv6_hdr(skb)->saddr,
+				    &ipv6_hdr(skb)->daddr);
 		goto csum_error;
 	}

 	if (!pskb_pull(skb, sizeof(*hdr)))
 		goto discard_it;

 	hdr = icmp6_hdr(skb);

 	type = hdr->icmp6_type;

 	ICMP6MSGIN_INC_STATS(dev_net_rcu(dev), idev, type);

 	switch (type) {
 	case ICMPV6_ECHO_REQUEST:
 		if (!net->ipv6.sysctl.icmpv6_echo_ignore_all)
 			reason = icmpv6_echo_reply(skb);
 		break;
 	case ICMPV6_EXT_ECHO_REQUEST:
 		if (!net->ipv6.sysctl.icmpv6_echo_ignore_all &&
 		    READ_ONCE(net->ipv4.sysctl_icmp_echo_enable_probe))
 			reason = icmpv6_echo_reply(skb);
 		break;

 	case ICMPV6_ECHO_REPLY:
 	case ICMPV6_EXT_ECHO_REPLY:
 		ping_rcv(skb);
 		return 0;

 	case ICMPV6_PKT_TOOBIG:
 		/* BUGGG_FUTURE: if packet contains rthdr, we cannot update
 		   standard destination cache. Seems, only "advanced"
 		   destination cache will allow to solve this problem
 		   --ANK (980726)
 		 */
 		if (!pskb_may_pull(skb, sizeof(struct ipv6hdr)))
 			goto discard_it;
 		hdr = icmp6_hdr(skb);

 		/* to notify */
 		fallthrough;
 	case ICMPV6_DEST_UNREACH:
 	case ICMPV6_TIME_EXCEED:
 	case ICMPV6_PARAMPROB:
 		reason = icmpv6_notify(skb, type, hdr->icmp6_code,
 				       hdr->icmp6_mtu);
 		break;

 	case NDISC_ROUTER_SOLICITATION:
 	case NDISC_ROUTER_ADVERTISEMENT:
 	case NDISC_NEIGHBOUR_SOLICITATION:
 	case NDISC_NEIGHBOUR_ADVERTISEMENT:
 	case NDISC_REDIRECT:
 		reason = ndisc_rcv(skb);
 		break;

 	case ICMPV6_MGM_QUERY:
 		igmp6_event_query(skb);
 		return 0;

 	case ICMPV6_MGM_REPORT:
 		igmp6_event_report(skb);
 		return 0;

 	case ICMPV6_MGM_REDUCTION:
 	case ICMPV6_NI_QUERY:
 	case ICMPV6_NI_REPLY:
 	case ICMPV6_MLD2_REPORT:
 	case ICMPV6_DHAAD_REQUEST:
 	case ICMPV6_DHAAD_REPLY:
 	case ICMPV6_MOBILE_PREFIX_SOL:
 	case ICMPV6_MOBILE_PREFIX_ADV:
 		break;

 	default:
 		/* informational */
 		if (type & ICMPV6_INFOMSG_MASK)
 			break;

 		net_dbg_ratelimited("icmpv6: msg of unknown type [%pI6c > %pI6c]\n",
-				    saddr, daddr);
+				    &ipv6_hdr(skb)->saddr,
+				    &ipv6_hdr(skb)->daddr);

 		/*
 		 * error of unknown type.
 		 * must pass to upper level
 		 */

 		reason = icmpv6_notify(skb, type, hdr->icmp6_code,
 				       hdr->icmp6_mtu);
 	}

 	/* until the v6 path can be better sorted assume failure and
 	 * preserve the status quo behaviour for the rest of the paths to here
 	 */
 	if (reason)
 		kfree_skb_reason(skb, reason);
 	else
 		consume_skb(skb);

 	return 0;

 csum_error:
 	reason = SKB_DROP_REASON_ICMP_CSUM;
 	__ICMP6_INC_STATS(dev_net_rcu(dev), idev, ICMP6_MIB_CSUMERRORS);
 discard_it:
 	__ICMP6_INC_STATS(dev_net_rcu(dev), idev, ICMP6_MIB_INERRORS);
 drop_no_count:
 	kfree_skb_reason(skb, reason);
 	return 0;
 }



